// =====================================================================
//  CONFIGURACIÓN DEL SOC — edita solo este bloque
// =====================================================================
const CFG = {
  wazuhApi: 'https://192.168.100.10:55000',   // API del manager
  dashboard: 'https://192.168.100.10',        // Wazuh Dashboard
  // IPs que NUNCA se bloquean (servidor, gateway, analista, loopback)
  allowlist: ['192.168.100.10', '192.168.100.1', '127.0.0.1', '::1'],
  // IDs de agentes Red Hat (usan firewalld-drop en lugar de firewall-drop)
  agentesRhel: ['004'],
  // Reglas en las que n8n ejecuta contención adicional vía API
  // (UC-01/UC-02 ya se bloquean de forma nativa con Active Response)
  reglasContencion: ['100112', '40112'],
  // Ventana anti-spam: misma regla + agente + IP no se notifica de nuevo
  ventanaDedupMin: 5,
  zonaHoraria: 'America/Lima',
};
// =====================================================================

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const severidad = (n) => {
  if (n >= 12) return { nombre: 'CRÍTICA', icono: '🔴', sla: '15 min' };
  if (n >= 10) return { nombre: 'ALTA', icono: '🟠', sla: '1 h' };
  if (n >= 7) return { nombre: 'MEDIA', icono: '🟡', sla: '4 h' };
  return { nombre: 'BAJA', icono: '🔵', sla: '24 h' };
};

const ipValida = (ip) => /^(\d{1,3}\.){3}\d{1,3}$/.test(ip || '') || /^[0-9a-f:]+:[0-9a-f:]*$/i.test(ip || '');

const estado = $getWorkflowStaticData('global');
estado.vistos = estado.vistos || {};
const ahora = Date.now();
// Limpieza de entradas antiguas
for (const k of Object.keys(estado.vistos)) {
  if (ahora - estado.vistos[k] > CFG.ventanaDedupMin * 60000) delete estado.vistos[k];
}

const salida = [];

for (const item of $input.all()) {
  // El webhook entrega la alerta en body; si se prueba con datos pegados, en la raíz
  const a = item.json.body ?? item.json;
  const rule = a.rule ?? {};
  const agent = a.agent ?? {};
  const data = a.data ?? {};
  const win = data.win?.eventdata ?? {};

  const nivel = Number(rule.level ?? 0);
  const sev = severidad(nivel);
  const srcip = data.srcip || win.ipAddress || '';
  const usuario = data.dstuser || data.srcuser || win.targetUserName || win.subjectUserName || win.user || data.win?.logFileCleared?.subjectUserName || '';
  const mitreIds = rule.mitre?.id ?? [];
  const mitreTacticas = rule.mitre?.tactic ?? [];
  const esWindows = Boolean(data.win) || (a.decoder?.name ?? '').includes('windows');

  // Comando de bloqueo según el sistema del agente (nombre definido en ossec.conf)
  let comandoBloqueo = 'firewall-drop';
  if (esWindows) comandoBloqueo = 'netsh';
  else if (CFG.agentesRhel.includes(String(agent.id))) comandoBloqueo = 'firewalld-drop';

  const contener =
    CFG.reglasContencion.includes(String(rule.id)) &&
    ipValida(srcip) &&
    !CFG.allowlist.includes(srcip) &&
    agent.id && agent.id !== '000';

  const claveDedup = `${rule.id}|${agent.id}|${srcip}`;
  const duplicada = Boolean(estado.vistos[claveDedup]);
  if (!duplicada) estado.vistos[claveDedup] = ahora;

  const hora = new Date(a.timestamp ?? ahora).toLocaleString('es-PE', { timeZone: CFG.zonaHoraria });

  const lineas = [
    `${sev.icono} <b>[${sev.nombre}] Wazuh · Regla ${esc(rule.id)} (nivel ${nivel})</b>`,
    `<b>Descripción:</b> ${esc(rule.description)}`,
    `<b>Equipo:</b> ${esc(agent.name)} (ID ${esc(agent.id)}${agent.ip ? ' · ' + esc(agent.ip) : ''})`,
  ];
  if (srcip) lineas.push(`<b>IP origen:</b> <code>${esc(srcip)}</code>`);
  if (usuario) lineas.push(`<b>Usuario:</b> ${esc(usuario)}`);
  if (mitreIds.length) lineas.push(`<b>MITRE ATT&amp;CK:</b> ${esc(mitreIds.join(', '))}${mitreTacticas.length ? ' · ' + esc(mitreTacticas.join(', ')) : ''}`);
  if (data.virustotal?.source?.file) lineas.push(`<b>Archivo:</b> <code>${esc(data.virustotal.source.file)}</code> (${esc(data.virustotal.positives)} motores)`);
  if (a.syscheck?.path && !data.virustotal) lineas.push(`<b>Archivo:</b> <code>${esc(a.syscheck.path)}</code> (${esc(a.syscheck.event)})`);
  lineas.push(`<b>Hora:</b> ${esc(hora)} · <b>SLA:</b> ${sev.sla}`);
  lineas.push(`<b>Acción automática:</b> ${contener ? `contención solicitada (${comandoBloqueo} sobre ${esc(srcip)})` : 'solo notificación'}`);
  lineas.push(`<b>ID alerta:</b> <code>${esc(a.id)}</code>`);
  lineas.push(`<a href="${CFG.dashboard}">Abrir Wazuh Dashboard</a>`);

  salida.push({
    json: {
      alerta_id: a.id,
      timestamp: a.timestamp,
      nivel,
      severidad: sev.nombre,
      regla_id: String(rule.id ?? ''),
      descripcion: rule.description,
      grupos: rule.groups ?? [],
      mitre: mitreIds,
      agente: agent.name,
      agente_id: String(agent.id ?? ''),
      srcip,
      usuario,
      contener: Boolean(contener) && !duplicada,
      comando_bloqueo: comandoBloqueo,
      notificar: !duplicada,
      api: CFG.wazuhApi,
      mensaje: lineas.join('\n'),
    },
  });
}

return salida;
